const weapons={};for(const [id,name,type,hands,power,range,stat] of [['sword','ดาบฝึก','sword',1,5,1,'STR'],['greatsword','ดาบใหญ่ฝึก','sword',2,9,1,'STR'],['greataxe','ขวานใหญ่ฝึก','axe',2,10,1,'STR'],['spear','หอกยาวฝึก','spear',2,8,2,'STR'],['shortspear','หอกสั้นฝึก','spear',1,5,1,'STR'],['dagger','มีดฝึก','dagger',1,4,1,'DEX'],['bow','ธนูฝึก','bow',2,6,3,'DEX'],['crossbow','หน้าไม้ฝึก','crossbow',2,7,3,'DEX'],['staff','คทาฝึก','staff',2,4,2,'INT'],['mace','กระบองฝึก','mace',1,5,1,'STR']])weapons[id]={id,name,type,hands,power,range,stat,level:1};
const clone=x=>JSON.parse(JSON.stringify(x));
const uniqueBudgets={human:10,elf:8,dwarf:9,vampire:6,cat:8,dragonborn:6};
function baseStats(d){return Object.fromEntries(stats.map((k,i)=>[k,d.v>=3?raceBases[d.race][i]:8]));}
function uniqueBudget(d){return d.v>=3?uniqueBudgets[d.race]:8;}
function sharedCost(d){return profCost(d)+(d.v>=2?uniqueCost(d):0);}
function uniqueCost(d){if(d.unique===null)return 0;const u=uniques.find(u=>u.id===d.unique);return u?(d.v<3?3:u.price):Infinity;}
function draft(){const d={v:3,gender:'unspecified',mode:'manual',race:'human',job:'warrior',rolled:false,offers:[],unique:null,human:['STR','DEX','CON'],profs:{},weapon:'greatsword',name:''};d.base=baseStats(d);return d;}
function statCost(d,k,value=d.base[k]){if(!Number.isInteger(value)||value<baseStats(d)[k]||value>15)return 1000;const absolute=v=>v<=13?v-7:({14:8,15:10}[v]??1000);return absolute(value)-absolute(baseStats(d)[k]);}
function cost(d){return stats.reduce((n,k)=>n+statCost(d,k),0);}
function profCost(d){return Object.values(d.profs).reduce((n,x)=>n+({D:1,C:3}[x]??1000),0);}
function roll(d,random=Math.random){if(d.rolled)throw Error('สุ่มได้ครั้งเดียวต่อตัวละคร');const out=clone(d),pick=a=>a[Math.min(a.length-1,Math.floor(random()*a.length))];out.race=pick(Object.keys(races));out.job=pick(Object.keys(classes));out.mode='random';out.rolled=true;out.offers=[];if(d.v>=2){out.weapon=classes[out.job].starter[0];if(d.v>=3){out.base=baseStats(out);if(sharedCost(out)>uniqueBudget(out))out.profs={};}return out;}let pool=uniques.map(x=>x.id);while(out.offers.length<3){const id=pick(pool);out.offers.push(id);pool=pool.filter(x=>x!==id);}out.unique=null;out.weapon=classes[out.job].starter[0];return out;}
function validateDraft(d){if(!d||![1,2,3].includes(d.v)||!races[d.race]||!classes[d.job]||!['manual','random'].includes(d.mode)||typeof d.rolled!=='boolean'||!d.base||stats.some(k=>!Number.isInteger(d.base[k])||d.base[k]<baseStats(d)[k]||d.base[k]>15)||cost(d)>27||!d.profs||Array.isArray(d.profs)||Object.entries(d.profs).some(([k,v])=>!profs[k]||!['D','C'].includes(v))||sharedCost(d)>uniqueBudget(d)||!Array.isArray(d.human)||d.human.length!==3||new Set(d.human).size!==3||d.human.some(k=>!stats.includes(k))||!classes[d.job].starter.includes(d.weapon))throw Error('แต้มสร้างตัวละครหรืออุปกรณ์ไม่ถูกต้อง');if(d.v>=3&&!Object.hasOwn(genders,d.gender))throw Error('เลือกเพศตัวละครให้ถูกต้อง');if(d.v===1){if(!Array.isArray(d.offers)||d.rolled&&(d.mode!=='random'||d.offers.length!==3||new Set(d.offers).size!==3||d.offers.some(k=>!uniques.some(u=>u.id===k))||d.unique!==null&&!d.offers.includes(d.unique))||!d.rolled&&(d.mode!=='manual'||d.offers.length||d.unique!==null))throw Error('ผลสุ่มไม่ถูกต้อง');}else if(!Array.isArray(d.offers)||d.offers.length||d.mode!==(d.rolled?'random':'manual')||uniqueCost(d)>uniqueBudget(d))throw Error('แต้ม Unique หรือผลสุ่มไม่ถูกต้อง');return clone(d);}
function upgradeDraft(input){const d=validateDraft(input);if(d.v===3)return d;const next={...d,v:3,gender:d.gender||'unspecified',offers:[]};for(const k of stats)next.base[k]=Math.max(next.base[k],baseStats(next)[k]);if(cost(next)>27)next.base=baseStats(next);if(sharedCost(next)>uniqueBudget(next))next.profs={};return validateDraft(next);}
function changeRace(input,race){const d=clone(input);if(!races[race])throw Error('ไม่พบเผ่า');d.race=race;d.base=baseStats(d);if(sharedCost(d)>uniqueBudget(d))d.profs={};return validateDraft(d);}
function finalStats(d){const out={...d.base},bonus=d.race==='human'?Object.fromEntries(d.human.map(k=>[k,1])):races[d.race].bonus;for(const [k,v] of Object.entries(bonus))out[k]+=v;return out;}
function recommend(d){const out=clone(d),order=[classes[d.job].primary,'CON',...stats].filter((v,i,a)=>a.indexOf(v)===i);order.forEach((k,i)=>out.base[k]=Math.max(baseStats(out)[k],[15,15,13,10,10,8][i]));while(cost(out)>27){const k=[...order].reverse().find(k=>out.base[k]>baseStats(out)[k]);out.base[k]--;}
while(cost(out)<27){const k=order.find(k=>out.base[k]<15&&cost({...out,base:{...out.base,[k]:out.base[k]+1}})<=27);if(!k)break;out.base[k]++;}
const weapon=weapons[out.weapon],primary=profs[weapon.type]?weapon.type:'arcane',extra=d.job==='knight'?'shield':d.job==='priest'?'healing':d.job==='alchemist'?'alchemy':d.job==='mage'?'fire':'light';out.profs={};let left=uniqueBudget(out)-(out.v>=2?uniqueCost(out):0);for(const k of [...new Set([primary,extra,'survival','perception','stealth','speech'])]){if(left<=0)break;const grade=left>=3?'C':'D';out.profs[k]=grade;left-=grade==='C'?3:1;}return out;}
function build(d,name){d=validateDraft(d);if(typeof name!=='string'||!name.trim()||name.trim().length>30)throw Error('ตั้งชื่อ 1–30 ตัวอักษร');if(d.v===1&&d.rolled&&!d.unique)throw Error('เลือก Unique หนึ่งสกิลก่อน');return {name:name.trim(),gender:d.gender||'unspecified',appearance:Model.validate(d.appearance,d.gender),race:d.race,job:d.job,level:1,xp:0,stats:finalStats(d),design:1,creation:d,unique:d.unique,skills:[...classes[d.job].skills],proficiencyGrades:{...d.profs},practice:{},equipment:{main:d.weapon,off:d.job==='knight'?'shield':null,armor:classes[d.job].armor},inventory:{potions:d.job==='alchemist'?5:3,reagents:3,weapons:[d.weapon]},duelTrials:0};}
function equip(c,main,off=null){const a=weapons[main],b=off==='shield'?null:weapons[off],job=classes[c.job];if(!a||!job||!job.weapons.includes(a.type)||c.level<a.level||off&&a.hands===2||off&&off!=='shield'&&(!b||b.hands!==1||!job.weapons.includes(b.type)||c.level<b.level)||off==='shield'&&c.job!=='knight'||b&&!c.proficiencyGrades?.dual)throw Error('คลาส เลเวล หรือความชำนาญอาวุธคู่ไม่ผ่าน');const owned=c.inventory?.weapons||[];if(!owned.includes(main)||b&&(!owned.includes(off)||main===off&&owned.filter(k=>k===main).length<2))throw Error('ไม่มีอาวุธครบทั้งสองชิ้นในกระเป๋า');return {...c.equipment,main,off};}
function gain(c,key,n){if(!profs[key]&&key!=='dual')return;c.practice??={};c.proficiencyGrades??={};c.practice[key]=(c.practice[key]||0)+n*(c.unique==='talent'?2:1);const grade=c.proficiencyGrades[key];if(!grade&&c.practice[key]>=20)c.proficiencyGrades[key]='D';if(c.proficiencyGrades[key]==='D'&&c.practice[key]>=100)c.proficiencyGrades[key]='C';/* B–S require explicit trials; never auto-promote. */}
